data.nginx.conf:
pid /tmp/nginx.pid;
error_log /dev/stderr warn;
worker_processes 1;
events { worker_connections 128; }
http {
 access_log off;
 client_max_body_size 2m;
 client_body_temp_path /tmp/client_temp;
 proxy_temp_path /tmp/proxy_temp;
 fastcgi_temp_path /tmp/fastcgi_temp;
 uwsgi_temp_path /tmp/uwsgi_temp;
 scgi_temp_path /tmp/scgi_temp;
 proxy_connect_timeout 3s;
 proxy_read_timeout 10s;
 server {
  listen 8080;
  location = /ready { proxy_pass http://127.0.0.1:3200/ready; }
  location ~ ^(/api/(echo|search|traces/[a-fA-F0-9]+)|/metrics)$ {
   if ($request_method != GET) { return 405; }
   auth_basic "Aegis telemetry";
   auth_basic_user_file /run/telemetry-auth/query.htpasswd;
   proxy_pass http://127.0.0.1:3200;
  }
  location / { return 404; }
 }
 server {
  listen 8081;
  location = /v1/traces {
   if ($request_method != POST) { return 405; }
   auth_basic "Aegis ingest";
   auth_basic_user_file /run/telemetry-auth/ingest.htpasswd;
   proxy_pass http://127.0.0.1:4318;
  }
  location / { return 404; }
 }
}
